    return total

def get_noOfways(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

def dict_depth(d):
    if not isinstance(d, (dict, list, tuple)):
        return 0
    if isinstance(d, dict):
        if not d:
            return 1
        return 1 + max(dict_depth(v) for v in d.values())
    else:  # list or tuple
        if not d:
            return 1
        return 1 + max(dict_depth(item) for item in d)

