from typing import List, Union

def concatenate(strings: List[Union[str, int]]) -> int:
    """ Concatenate list of strings or integers into a single string and return its length. """
    concatenated = ''.join(str(s) for s in strings)
    return len(concatenated)

def check_dict_case(d):
    if not d:
        return 'Empty'
    keys = d.keys()
    # Check all keys are strings and all lowercase
    if all(isinstance(k, str) for k in keys) and all(k.islower() for k in keys):
        return 1
    # Check all keys are strings and all uppercase
