def odd_Num_Sum(n):
    # The first n odd numbers: 1, 3, 5, ..., (2n-1)
    # Corresponding even numbers: 2, 4, 6, ..., 2n
    # Sum the fourth powers of these even numbers
    return sum((2 * i) ** 4 for i in range(1, n + 1))

