def sequence(n):
    if not isinstance(n, int) or n < 1:
        raise ValueError("Input must be a positive integer starting from 1")
    seq = [0, 1]
    for i in range(2, n + 1):
        seq.append(seq[seq[i - 1]] + seq[i - seq[i - 1]])
    return seq[n]

